-- Généré par scripts/import-fff.js depuis data/j2-2026-fff.json (epreuves.fff.fr, pages « Le match » de la J2 (20/09/2026), relevées le 29/09/2026)
-- Ne pas exécuter deux fois.
select m.competition, m.home_name, m.away_name,
  (select count(*) from public.events e where e.match_id = m.id and e.k = 'goal' and e.t = 'H') || ' – ' ||
  (select count(*) from public.events e where e.match_id = m.id and e.k = 'goal' and e.t = 'A') as score,
  (select count(*) from public.events e where e.match_id = m.id) as actions
from public.matches m where m.id in ('5cdaa7c5-0ea6-4c97-a578-eb9971defdcf', '21d330cb-aa5e-432a-a2c3-916e80edf642', '7b5f760a-305e-4c85-b3d6-a5bee1542ef1', '28d81def-6e99-4949-b61c-65de534f3ce4') order by m.equipe;
